\label{ass:subgaussian}
For any $t\in[T]$ and $\lambda\in\mathbb{R}$, the noise $\epsilon_t$ satisfies
\begin{align*}
\log\mathbb{E}[\exp(\lambda\epsilon_t)|\mathcal{G}_t]\le\lambda^2/8\quad\text{almost surely}.
\end{align*}

\label{def:dc_A}
The decoupling coefficient for FGTS with the cumulative feel-good exploration term is the smallest nonnegative number $\operatorname{dc}$ such that, for every $\gamma>0$, context $x\in\mathcal{X}$, and joint distribution $P$ over $\mathcal{F}\times\mathcal{A}$, we have
\begin{align*}
\mathbb{E}_{(f, a)\sim P}[f(x, a)-f_*(x, a)]\le\frac{\operatorname{dc}}{4\gamma}+\gamma\cdot\mathbb{E}_{a\sim P}\mathbb{E}_{f\sim P}[(f(x, a)-f_*(x, a))^2].
\end{align*}
The expectations on the right use independent draws from the two marginals of $P$.

\label{def:dc_B}
Let $Z=(z_1,\ldots,z_T)$, where $z_t=(x_t,a_t)\in\mathcal{X}\times\mathcal{A}$. The decoupling coefficient for FGTS with the current-step feel-good exploration term is $\operatorname{dc}_T(\mathcal{F})=\sup_Z\operatorname{dc}(\mathcal{F},Z)$, where $\operatorname{dc}(\mathcal{F},Z)$ is the smallest nonnegative number such that, for every $0<\gamma\le1$ and every sequence $f_1,\ldots,f_T\in\mathcal{F}$, we have
\begin{align*}
\sum_{t=1}^T(f_t(z_t)-f_*(z_t))\le\gamma\sum_{t=1}^T\sum_{s=1}^{t-1}(f_t(z_s)-f_*(z_s))^2+\frac{\operatorname{dc}(\mathcal{F}, Z)}{4\gamma}.
\end{align*}
This is the contextual-bandit form of the online decoupling inequality in \citet{dann2021provably}. We abbreviate $\operatorname{dc}_T(\mathcal{F})$ as $\operatorname{dc}_T$.

\label{thm:A}
Under Assumption~\ref{ass:subgaussian}, suppose that $0<\operatorname{dc}<\infty$ and $0<p_0(\mathcal{F}_{1/T})<1$. For $\delta\in(0,1/3)$, choose the hyperparameters of FGTS with the cumulative feel-good exploration term as
\begin{align*}
\eta=0.2,\quad\lambda=\sqrt{\frac{\log p_0^{-1}(\mathcal{F}_{1/T})}{5T\cdot\operatorname{dc}}}.
\end{align*}
Then with probability at least $1-3\delta$, the regret satisfies
\begin{align*}
\operatorname{Regret}(T)
&\le2\sqrt{5T\cdot\operatorname{dc}\cdot\log p_0^{-1}(\mathcal{F}_{1/T})}
+4\sqrt{\frac{T\log p_0^{-1}(\mathcal{F}_{1/T})}{5\operatorname{dc}}}\\
&\quad+\bigg(4\sqrt T+\sqrt{\frac{\operatorname{dc}}{5\log p_0^{-1}(\mathcal{F}_{1/T})}}\bigg)\sqrt{2\log(1/\delta)}\\
&\quad+\sqrt{\frac{5T\operatorname{dc}}{\log p_0^{-1}(\mathcal{F}_{1/T})}}\log(1/\delta)
+\sqrt{\frac{\operatorname{dc}}{5T\log p_0^{-1}(\mathcal{F}_{1/T})}}+1.
\end{align*}

\label{thm:B}
Under Assumption~\ref{ass:subgaussian}, suppose that $\operatorname{dc}_T>0$ and $0<p_0(\mathcal{F}_{1/T})<1$. For $\delta\in(0,1)$, choose the hyperparameters of FGTS with the current-step feel-good exploration term as
\begin{align*}
\eta=0.5,\quad\lambda=\max\Big\{\frac14, \sqrt{T\operatorname{dc}_T^{-1}\log(p_0^{-1}(\mathcal{F}_{1/T}))}\Big\}.
\end{align*}
Then with probability at least $1-\delta$ the regret satisfies
\begin{align*}
\operatorname{Regret}(T)\le2\sqrt{T\operatorname{dc}_T\log(p_0^{-1}(\mathcal{F}_{1/T}))}+3+\sqrt{\frac{T\operatorname{dc}_T}{\log(p_0^{-1}(\mathcal{F}_{1/T}))}}\log(T/\delta).
\end{align*}

In order to use the decoupling coefficient which is related to the expectation with respect to the joint distribution, we firstly perform the following decomposition of the regret:
\begin{align*}
\operatorname{Regret}(T)&=\underbrace{\sum_{t=1}^T\big\{(f_*(x_t, a_t^*)-f_*(x_t, a_t))-\mathbb{E}[f_*(x_t, a_t^*)-f_*(x_t, a_t)|\mathcal{F}_{t-1}]\big\}}_{I_1}\\
&\quad+\underbrace{\sum_{t=1}^T\mathbb{E}[f_*(x_t, a_t^*)-f_*(x_t, a_t)|\mathcal{F}_{t-1}]}_{I_2}.
\end{align*}
By Azuma-Hoeffding's inequality, we have with probability at least $1-\delta$,
\begin{align*}
I_1\le\sqrt{32T\log(1/\delta)}.
\end{align*}
For the term $I_2$, apply Definition~\ref{def:dc_A} conditionally on $\mathcal{F}_{t-1},x_t,\mathcal{A}_t$ and then average over the current context and action set. The auxiliary draw $\widetilde f\sim p_t^A$ is independent of $a_t$ given this information. This gives
\begin{align*}
&\mathbb{E}[f_*(x_t, a_t^*)-f_*(x_t, a_t)|\mathcal{F}_{t-1}]\\
&=\mathbb{E}[f_t(x_t, a_t)-f_*(x_t, a_t)-\operatorname{FG}_t(f_t)|\mathcal{F}_{t-1}]\\
&\le\frac{\operatorname{dc}}{4\gamma}+\mathbb{E}\Big[\mathbb{E}_{\widetilde f\sim p_t^A}[\gamma\operatorname{LS}_t(\widetilde f)-\operatorname{FG}_t(\widetilde f)]\Big|\mathcal{F}_{t-1}\Big],
\end{align*}
so with probability at least $1-\delta$,
\begin{align*}
\operatorname{Regret}(T)\le\sqrt{32T\log(1/\delta)}+\frac{T\cdot\operatorname{dc}}{4\gamma}+\sum_{t=1}^T\mathbb{E}\Big[\mathbb{E}_{\widetilde f\sim p_t^A}[\gamma\operatorname{LS}_t(\widetilde f)-\operatorname{FG}_t(\widetilde f)]\Big|\mathcal{F}_{t-1}\Big].
\end{align*}
By Markov's inequality, for any $L_\delta$, we have
\begin{align*}
&\mathbb{P}\bigg\{\lambda\sum_{t=1}^T\mathbb{E}\Big[\mathbb{E}_{\widetilde f\sim p_t^A}[\gamma\operatorname{LS}_t(\widetilde f)-\operatorname{FG}_t(\widetilde f)]\Big|\mathcal{F}_{t-1}\Big]\ge-\log Z_{T+1}^A+L_\delta\bigg\}\\
&=\mathbb{P}\bigg\{Z_{T+1}^A\cdot\exp\bigg(\lambda\sum_{t=1}^T\mathbb{E}\Big[\mathbb{E}_{\widetilde f\sim p_t^A}[\gamma\operatorname{LS}_t(\widetilde f)-\operatorname{FG}_t(\widetilde f)]\Big|\mathcal{F}_{t-1}\Big]\bigg)\ge e^{L_\delta}\bigg\}\\
&\le e^{-L_\delta}\mathbb{E}\bigg[Z_{T+1}^A\cdot\exp\bigg(\lambda\sum_{t=1}^T\mathbb{E}\Big[\mathbb{E}_{\widetilde f\sim p_t^A}[\gamma\operatorname{LS}_t(\widetilde f)-\operatorname{FG}_t(\widetilde f)]\Big|\mathcal{F}_{t-1}\Big]\bigg)\bigg]\\
&=e^{-L_\delta}\mathbb{E}\bigg[\mathbb{E}[Z_{T+1}^A|\mathcal{F}_{T-1}]\cdot\exp\bigg(\lambda\sum_{t=1}^T\mathbb{E}\Big[\mathbb{E}_{\widetilde f\sim p_t^A}[\gamma\operatorname{LS}_t(\widetilde f)-\operatorname{FG}_t(\widetilde f)]\Big|\mathcal{F}_{t-1}\Big]\bigg)\bigg]
\end{align*}
For the term $\mathbb{E}[Z_{T+1}^A|\mathcal{F}_{T-1}]$, we use the following lemma:
\begin{lemma}\label{lemma:telescope}
Suppose that $0<\eta\le0.2$ and $\lambda>0$. Under Assumption~\ref{ass:subgaussian}, the Type-A normalizer satisfies
\begin{align*}
\mathbb{E}[Z_{t+1}^A|\mathcal{F}_{t-1}]
\le Z_t^A\cdot\exp\Big(\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}[-0.25\eta\operatorname{LS}_t(f)+\lambda\operatorname{FG}_t(f)]\Big|\mathcal{F}_{t-1}\Big]+4\lambda^2\Big).
\end{align*}
\end{lemma}
With Lemma~\ref{lemma:telescope}, we have
\begin{align*}
&\mathbb{P}\bigg\{\lambda\sum_{t=1}^T\mathbb{E}\Big[\mathbb{E}_{\widetilde f\sim p_t^A}[\gamma\operatorname{LS}_t(\widetilde f)-\operatorname{FG}_t(\widetilde f)]\Big|\mathcal{F}_{t-1}\Big]\ge-\log Z_{T+1}^A+L_\delta\bigg\}\\
&\le e^{-L_\delta}\mathbb{E}\bigg[Z_T^A\cdot\exp\bigg(\lambda\sum_{t=1}^{T-1}\mathbb{E}\Big[\mathbb{E}_{\widetilde f\sim p_t^A}[\gamma\operatorname{LS}_t(\widetilde f)-\operatorname{FG}_t(\widetilde f)]\Big|\mathcal{F}_{t-1}\Big]\bigg)\\
&\quad\cdot\exp\Big(\mathbb{E}\Big[\mathbb{E}_{\widetilde f\sim p_T^A}[(\gamma\lambda-0.25\eta)\operatorname{LS}_T(\widetilde f)]\Big|\mathcal{F}_{T-1}\Big]+4\lambda^2\Big)\bigg]\\
&\le\cdots\\
&\le\exp(4T\lambda^2-L_\delta),
\end{align*}
where the second inequality holds because $\gamma\lambda\le0.25\eta$, and the last inequality follows by repeating this step down to $Z_1^A=1$. Therefore, taking
\begin{align*}
L_\delta=4T\lambda^2+\log(1/\delta),
\end{align*}
then the following event holds with probability at least $1-\delta$:
\begin{align*}
\sum_{t=1}^T\mathbb{E}\Big[\mathbb{E}_{\widetilde f\sim p_t^A}[\gamma\operatorname{LS}_t(\widetilde f)-\operatorname{FG}_t(\widetilde f)]\Big|\mathcal{F}_{t-1}\Big]\le\frac{-\log Z_{T+1}^A+\log(1/\delta)}{\lambda}+4T\lambda.
\end{align*}
The following lemma provides the bound for $-\log Z_{T+1}^A$:
\begin{lemma}\label{lemma:ZTA}
Under Assumption~\ref{ass:subgaussian}, for any $h>0$ with $p_0(\mathcal{F}_h)>0$ and $\delta\in(0,1)$, with probability at least $1-\delta$, we have
\begin{align*}
-\log Z_{T+1}^A\le\eta h\sqrt{2T\log(1/\delta)}+\eta Th^2+\lambda Th+\log p_0^{-1}(\mathcal{F}_h).
\end{align*}
\end{lemma}
With Lemma~\ref{lemma:ZTA}, combining all the above, with probability at least $1-3\delta$, we have
\begin{align*}
\operatorname{Regret}(T)
&\le(4+\eta h/\lambda)\sqrt{2T\log(1/\delta)}+\frac{T\cdot\operatorname{dc}}{4\gamma}+4T\lambda\\
&\quad+\frac{\eta Th^2}{\lambda}+Th+\frac{\log p_0^{-1}(\mathcal{F}_h)+\log(1/\delta)}{\lambda}.
\end{align*}
Set
\begin{align*}
h=T^{-1},\quad\eta=0.2,\quad\lambda=\sqrt{\frac{\log p_0^{-1}(\mathcal{F}_h)}{5T\cdot\operatorname{dc}}},\quad\gamma=0.05\lambda^{-1},
\end{align*}
then
\begin{align*}
\operatorname{Regret}(T)
&\le2\sqrt{5T\cdot\operatorname{dc}\cdot\log p_0^{-1}(\mathcal{F}_h)}
+4\sqrt{\frac{T\log p_0^{-1}(\mathcal{F}_h)}{5\operatorname{dc}}}\\
&\quad+\bigg(4\sqrt T+\sqrt{\frac{\operatorname{dc}}{5\log p_0^{-1}(\mathcal{F}_h)}}\bigg)\sqrt{2\log(1/\delta)}\\
&\quad+\sqrt{\frac{5T\operatorname{dc}}{\log p_0^{-1}(\mathcal{F}_h)}}\log(1/\delta)
+\sqrt{\frac{\operatorname{dc}}{5T\log p_0^{-1}(\mathcal{F}_h)}}+1.
\end{align*}

\label{lemma:telescope}
Suppose that $0<\eta\le0.2$ and $\lambda>0$. Under Assumption~\ref{ass:subgaussian}, the Type-A normalizer satisfies
\begin{align*}
\mathbb{E}[Z_{t+1}^A|\mathcal{F}_{t-1}]
\le Z_t^A\cdot\exp\Big(\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}[-0.25\eta\operatorname{LS}_t(f)+\lambda\operatorname{FG}_t(f)]\Big|\mathcal{F}_{t-1}\Big]+4\lambda^2\Big).
\end{align*}

\label{lemma:ZTA}
Under Assumption~\ref{ass:subgaussian}, for any $h>0$ with $p_0(\mathcal{F}_h)>0$ and $\delta\in(0,1)$, with probability at least $1-\delta$, we have
\begin{align*}
-\log Z_{T+1}^A\le\eta h\sqrt{2T\log(1/\delta)}+\eta Th^2+\lambda Th+\log p_0^{-1}(\mathcal{F}_h).
\end{align*}

According to the definition of the decoupling coefficient, for any $0<\gamma\le1$, the regret further satisfies
\begin{align*}
\operatorname{Regret}(T)\le\sum_{t=1}^T\bigg[\gamma\sum_{s=1}^{t-1}\operatorname{LS}_s(f_t)-\operatorname{FG}_t(f_t)\bigg]+\frac{\operatorname{dc}_T(\mathcal{F})}{4\gamma}.
\end{align*}
It then suffices to provide a high-probability upper bound of $\gamma\sum_{s=1}^{t-1}\operatorname{LS}_s(f_t)-\operatorname{FG}_t(f_t)$. By Markov's inequality, we have for any $C_t$,
\begin{align}
&\mathbb{P}\bigg[\gamma\sum_{s=1}^{t-1}\operatorname{LS}_s(f_t)-\operatorname{FG}_t(f_t)\ge C_t\bigg]\nonumber\\
&=\mathbb{P}\bigg[\exp\bigg(\gamma\lambda\sum_{s=1}^{t-1}\operatorname{LS}_s(f_t)-\lambda\operatorname{FG}_t(f_t)\bigg)\ge\exp(\lambda C_t)\bigg]\nonumber\\
&\le\exp(-\lambda C_t)\cdot\mathbb{E}\exp\bigg(\gamma\lambda\sum_{s=1}^{t-1}\operatorname{LS}_s(f_t)-\lambda\operatorname{FG}_t(f_t)\bigg)\nonumber\\
&=\exp(-\lambda C_t)\cdot\mathbb{E}\bigg[\frac1{Z_t^B}\mathbb{E}_{\widetilde f\sim p_0}\exp\bigg(\sum_{s=1}^{t-1}\big[2\eta\epsilon_s(\widetilde f(x_s, a_s)-f_*(x_s, a_s))+(\gamma\lambda-\eta)\operatorname{LS}_s(\widetilde f)\big]\bigg)\bigg].\label{eq:B_0}
\end{align}
where the last equality first conditions on $\mathcal{F}_{t-1},x_t,\mathcal{A}_t$ and then substitutes the posterior density in \eqref{eq:def_ptB}.
A key challenge is that the past noises $\epsilon_1,\ldots,\epsilon_{t-1}$ appear in both the numerator and the denominator $Z_t^B$. To solve this problem, we use the following lemma that provides a lower bound of $Z_t^B$:
\begin{lemma}\label{lemma:B_Zt}
For any $h>0$ with $p_0(\mathcal{F}_h)>0$, the Type-B normalizer satisfies
\begin{align*}
\frac1{Z_t^B}\le\frac1{p_0(\mathcal{F}_h)}\exp\bigg(\mathbb{E}_{f\sim p_0^h}\bigg[\sum_{s=1}^{t-1}\big[-2\eta\epsilon_s(f(x_s, a_s)-f_*(x_s, a_s))+\eta h^2\big]+\lambda h\bigg]\bigg).
\end{align*}
\end{lemma}
Lemma~\ref{lemma:B_Zt} converts $Z_t^B$, which is the expectation of the exponential, into the exponential of the expectation, thus enabling the joint analysis of the past noises $\epsilon_1,\ldots,\epsilon_{t-1}$ in the numerator and the denominator. We thus have
\begin{align}
&\mathbb{E}\bigg[\frac1{Z_t^B}\mathbb{E}_{\widetilde f\sim p_0}\exp\bigg(\sum_{s=1}^{t-1}\big[2\eta\epsilon_s(\widetilde f(x_s, a_s)-f_*(x_s, a_s))+(\gamma\lambda-\eta)\operatorname{LS}_s(\widetilde f)\big]\bigg)\bigg]\nonumber\\
&\le\frac{\exp(\lambda h)}{p_0(\mathcal{F}_h)}\mathbb{E}_{\widetilde f\sim p_0}\mathbb{E}\exp\bigg(\sum_{s=1}^{t-1}\big[2\eta\epsilon_s\{\widetilde f(x_s, a_s)-\mathbb{E}_{f\sim p_0^h}[f(x_s, a_s)]\}+(\gamma\lambda-\eta)\operatorname{LS}_s(\widetilde f)+\eta h^2\big]\bigg).\label{eq:B_1}
\end{align}
We use the following lemma to further bound the right-hand side:
\begin{lemma}\label{lemma:B_supermartingle}
Under Assumption~\ref{ass:subgaussian}, suppose that $0<\eta\le0.5$, $\gamma,\lambda>0$, and $\gamma\lambda\le\eta-\eta^2$. For any fixed $\widetilde f\in\mathcal{F}$ and $h>0$ with $p_0(\mathcal{F}_h)>0$, we have
\begin{align*}
&\mathbb{E}\exp\bigg(\sum_{s=1}^{t-1}\big[2\eta\epsilon_s\{\widetilde f(x_s, a_s)-\mathbb{E}_{f\sim p_0^h}[f(x_s, a_s)]\}+(\gamma\lambda-\eta)\operatorname{LS}_s(\widetilde f)+\eta h^2\big]\bigg)\\
&\le\exp(0.75(t-1)h^2).
\end{align*}
\end{lemma}
Plugging Lemma~\ref{lemma:B_supermartingle} and \eqref{eq:B_1} into \eqref{eq:B_0}, we have
\begin{align*}
\mathbb{P}\bigg[\gamma\sum_{s=1}^{t-1}\operatorname{LS}_s(f_t)-\operatorname{FG}_t(f_t)\ge C_t\bigg]\le\frac{\exp(\lambda h+0.75(t-1)h^2-\lambda C_t)}{p_0(\mathcal{F}_h)}.
\end{align*}
Let
\begin{align*}
C_t=h+\frac{0.75(t-1)h^2}{\lambda}+\frac{\log(p_0^{-1}(\mathcal{F}_h))}{\lambda}+\frac{\log(T/\delta)}{\lambda},
\end{align*}
and $\mathcal{E}_t$ be the event such that
\begin{align*}
\gamma\sum_{s=1}^{t-1}\operatorname{LS}_s(f_t)-\operatorname{FG}_t(f_t)\le C_t.
\end{align*}
Then $\mathcal{E}_t$ holds with probability at least $1-\delta/T$. Taking the union bound, we have the good event $\mathcal{E}:=\cap_{t\in[T]}\mathcal{E}_t$ holds with probability at least $1-\delta$. Under the good event $\mathcal{E}$, we have
\begin{align*}
\operatorname{Regret}(T)&\le\frac{\operatorname{dc}_T}{4\gamma}+\sum_{t=1}^TC_t\\
&=\frac{\operatorname{dc}_T}{4\gamma}+Th+\frac{3T(T-1)h^2}{8\lambda}+\frac{T\log(p_0^{-1}(\mathcal{F}_h))}{\lambda}+\frac{T\log(T/\delta)}{\lambda}.
\end{align*}
Let
\begin{align*}
h=T^{-1},\quad\eta=0.5,\quad\lambda=\max\Big\{\frac14, \sqrt{T\operatorname{dc}_T^{-1}\log(p_0^{-1}(\mathcal{F}_{1/T}))}\Big\},\quad\gamma=1/(4\lambda).
\end{align*}
The choice of $\lambda$ ensures that $0<\gamma\le1$ and $\gamma\lambda=\eta-\eta^2$. Since $\lambda\ge1/4$, the preceding bound gives
\begin{align*}
\operatorname{Regret}(T)\le\operatorname{dc}_T\lambda+3+\frac{T}{\lambda}\big[\log p_0^{-1}(\mathcal{F}_{1/T})+\log(T/\delta)\big].
\end{align*}
To verify the final substitution, write $D=\log p_0^{-1}(\mathcal{F}_{1/T})$ and $r=\sqrt{TD/\operatorname{dc}_T}$ within this proof. If $r\ge1/4$, substitute $\lambda=r$. If $r<1/4$ and $T\ge2$, Definition~\ref{def:dc_B} gives $\operatorname{dc}_T\le8T$, since $f_t(z_t)-f_*(z_t)\le2$. Consequently, the function
\begin{align*}
g(u)=\operatorname{dc}_Tu+\frac{T[D+\log(T/\delta)]}{u}
\end{align*}
satisfies, for $r\le u\le1/4$,
\begin{align*}
g'(u)=\operatorname{dc}_T-\frac{T[D+\log(T/\delta)]}{u^2}
\le8T-16T\log2<0.
\end{align*}
Thus $g(\lambda)\le g(r)$ in both cases, and
\begin{align*}
\operatorname{Regret}(T)\le2\sqrt{T\operatorname{dc}_T\log(p_0^{-1}(\mathcal{F}_{1/T}))}+3+\sqrt{\frac{T\operatorname{dc}_T}{\log(p_0^{-1}(\mathcal{F}_{1/T}))}}\log(T/\delta).
\end{align*}
For $T=1$, the same conclusion follows from $\operatorname{Regret}(1)\le2$.

\label{lemma:B_Zt}
For any $h>0$ with $p_0(\mathcal{F}_h)>0$, the Type-B normalizer satisfies
\begin{align*}
\frac1{Z_t^B}\le\frac1{p_0(\mathcal{F}_h)}\exp\bigg(\mathbb{E}_{f\sim p_0^h}\bigg[\sum_{s=1}^{t-1}\big[-2\eta\epsilon_s(f(x_s, a_s)-f_*(x_s, a_s))+\eta h^2\big]+\lambda h\bigg]\bigg).
\end{align*}

\label{lemma:B_supermartingle}
Under Assumption~\ref{ass:subgaussian}, suppose that $0<\eta\le0.5$, $\gamma,\lambda>0$, and $\gamma\lambda\le\eta-\eta^2$. For any fixed $\widetilde f\in\mathcal{F}$ and $h>0$ with $p_0(\mathcal{F}_h)>0$, we have
\begin{align*}
&\mathbb{E}\exp\bigg(\sum_{s=1}^{t-1}\big[2\eta\epsilon_s\{\widetilde f(x_s, a_s)-\mathbb{E}_{f\sim p_0^h}[f(x_s, a_s)]\}+(\gamma\lambda-\eta)\operatorname{LS}_s(\widetilde f)+\eta h^2\big]\bigg)\\
&\le\exp(0.75(t-1)h^2).
\end{align*}

We first notice that
\begin{align*}
Z_{t+1}^A=Z_t^A\cdot\mathbb{E}_{f\sim p_t^A}\exp(2\eta\epsilon_t(f(x_t, a_t)-f_*(x_t, a_t))-\eta\operatorname{LS}_t(f)+\lambda\operatorname{FG}_t(f)).
\end{align*}
Note that $Z_t^A$ and $p_t^A$ are $\mathcal{F}_{t-1}$-measurable. Taking the conditional expectation, we have
\begin{align*}
\mathbb{E}[Z_{t+1}^A|\mathcal{F}_{t-1}]&=Z_t^A\cdot\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}\mathbb{E}\big[\exp(2\eta\epsilon_t(f(x_t, a_t)-f_*(x_t, a_t))-\eta\operatorname{LS}_t(f)+\lambda\operatorname{FG}_t(f))\big|\mathcal{G}_t\big]\Big|\mathcal{F}_{t-1}\Big]\\
&\le Z_t^A\cdot\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}\exp((\eta^2/2-\eta)\operatorname{LS}_t(f)+\lambda\operatorname{FG}_t(f))\Big|\mathcal{F}_{t-1}\Big]\\
&\le Z_t^A\cdot\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}\exp(-0.9\eta\operatorname{LS}_t(f)+\lambda\operatorname{FG}_t(f))\Big|\mathcal{F}_{t-1}\Big],
\end{align*}
where the first inequality holds due to Assumption~\ref{ass:subgaussian}, and the second inequality holds because $\eta\le0.2$. To bound this exponential moment in terms of the mean loss and mean feel-good term, we use the Cauchy-Schwarz inequality:
\begin{align}
&\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}\exp(-0.9\eta\operatorname{LS}_t(f)+\lambda\operatorname{FG}_t(f))\Big|\mathcal{F}_{t-1}\Big]\nonumber\\
&\le\sqrt{\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}\exp(-1.8\eta\operatorname{LS}_t(f))\Big|\mathcal{F}_{t-1}\Big]}\cdot\sqrt{\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}\exp(2\lambda\operatorname{FG}_t(f))\Big|\mathcal{F}_{t-1}\Big]}.\label{eq:increment}
\end{align}
Since $e^z\le1+z+z^2/2$ for $z\le0$, we have
\begin{align}
&\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}\exp(-1.8\eta\operatorname{LS}_t(f))\Big|\mathcal{F}_{t-1}\Big]\nonumber\\
&\le\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}[1-1.8\eta\operatorname{LS}_t(f)+1.62\eta^2\operatorname{LS}_t^2(f)]\Big|\mathcal{F}_{t-1}\Big]\nonumber\\
&\le\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}[1-1.8\eta\operatorname{LS}_t(f)+1.296\eta\operatorname{LS}_t(f)]\Big|\mathcal{F}_{t-1}\Big]\nonumber\\
&\le1-0.5\eta\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}[\operatorname{LS}_t(f)]\Big|\mathcal{F}_{t-1}\Big]\nonumber\\
&\le\exp\Big(-0.5\eta\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}[\operatorname{LS}_t(f)]\Big|\mathcal{F}_{t-1}\Big]\Big),\label{eq:LS}
\end{align}
where the second inequality holds because $\eta\le0.2$ and $\operatorname{LS}_t(f)\le4$, and the last inequality holds because $1+z\le e^z$. For the term related to $\operatorname{FG}_t(f)$, by Hoeffding's lemma, since $\operatorname{FG}_t(f)\in[-2, 2]$, we have
\begin{align}
\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}\exp(2\lambda\operatorname{FG}_t(f))\Big|\mathcal{F}_{t-1}\Big]\le\exp(2\lambda\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}[\operatorname{FG}_t(f)]\Big|\mathcal{F}_{t-1}\Big]+8\lambda^2\Big).\label{eq:FG}
\end{align}
Plugging \eqref{eq:LS} and \eqref{eq:FG} into \eqref{eq:increment}, we have
\begin{align*}
&\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}\exp(-0.9\eta\operatorname{LS}_t(f)+\lambda\operatorname{FG}_t(f))\Big|\mathcal{F}_{t-1}\Big]\\
&\le\exp\Big(\mathbb{E}\Big[\mathbb{E}_{f\sim p_t^A}[-0.25\eta\operatorname{LS}_t(f)+\lambda\operatorname{FG}_t(f)]\Big|\mathcal{F}_{t-1}\Big]+4\lambda^2\Big).
\end{align*}

We use Lemma~\ref{lemma:KL_reg} with
\begin{align*}
P=p_0^h,\quad P_0=p_0,\quad U(f)=\sum_{t=1}^T\big[-2\eta\epsilon_t(f(x_t, a_t)-f_*(x_t, a_t))+\eta\operatorname{LS}_t(f)-\lambda\operatorname{FG}_t(f)\big].
\end{align*}
Then Lemma~\ref{lemma:KL_reg} gives
\begin{align*}
-\log Z_{T+1}^A\le\mathbb{E}_{f\sim p_0^h}\bigg[\sum_{t=1}^T\big[-2\eta\epsilon_t(f(x_t, a_t)-f_*(x_t, a_t))+\eta\operatorname{LS}_t(f)-\lambda\operatorname{FG}_t(f)\big]\bigg]+\operatorname{KL}(p_0^h\|p_0).
\end{align*}
Due to the definition of $\mathcal{F}_h$, for any $f\in\mathcal{F}_h$, we have
\begin{align*}
\operatorname{LS}_t(f)\le h^2,\quad-\operatorname{FG}_t(f)=f_*(x_t, a_t^*)-\max_{a\in\mathcal{A}_t}f(x_t, a)\le f_*(x_t, a_t^*)-f(x_t, a_t^*)\le h.
\end{align*}
For the KL divergence term, we have
\begin{align*}
\operatorname{KL}(p_0^h\|p_0)=\mathbb{E}_{f\sim p_0^h}\log\frac{p_0^h(f)}{p_0(f)}=\log p_0^{-1}(\mathcal{F}_h).
\end{align*}
Additionally, since $|\mathbb{E}_{f\sim p_0^h}f(x_t, a_t)-f_*(x_t, a_t)|\le h$, Lemma~\ref{lemma:subgaussian} gives that with probability at least $1-\delta$, we have
\begin{align*}
\sum_{t=1}^T\epsilon_t\cdot\mathbb{E}_{f\sim p_0^h}[f_*(x_t, a_t)-f(x_t, a_t)]\le h\sqrt{T/2\log(1/\delta)}.
\end{align*}
Combining all the above, we have
\begin{align*}
-\log Z_{T+1}^A\le\eta h\sqrt{2T\log(1/\delta)}+\eta Th^2+\lambda Th+\log p_0^{-1}(\mathcal{F}_h).
\end{align*}

We use Lemma~\ref{lemma:KL_reg} with
\begin{align*}
P=p_0^h,\quad P_0=p_0,\quad U(f)=\sum_{s=1}^{t-1}\big[-2\eta\epsilon_s(f(x_s, a_s)-f_*(x_s, a_s))+\eta\operatorname{LS}_s(f)\big]-\lambda\operatorname{FG}_t(f).
\end{align*}
Then Lemma~\ref{lemma:KL_reg} gives
\begin{align*}
\log\frac1{Z_t^B}\le\mathbb{E}_{f\sim p_0^h}\bigg[\sum_{s=1}^{t-1}\big[-2\eta\epsilon_s(f(x_s, a_s)-f_*(x_s, a_s))+\eta\operatorname{LS}_s(f)\big]-\lambda\operatorname{FG}_t(f)\bigg]+\operatorname{KL}(p_0^h\|p_0).
\end{align*}
Due to the definition of $\mathcal{F}_h$, for any $f\in\mathcal{F}_h$, we have
\begin{align*}
\operatorname{LS}_s(f)\le h^2,\quad-\operatorname{FG}_t(f)=f_*(x_t, a_t^*)-\max_{a\in\mathcal{A}_t}f(x_t, a)\le f_*(x_t, a_t^*)-f(x_t, a_t^*)\le h.
\end{align*}
For the KL divergence term, we have
\begin{align*}
\operatorname{KL}(p_0^h\|p_0)=\mathbb{E}_{f\sim p_0^h}\log\frac{p_0^h(f)}{p_0(f)}=\log p_0^{-1}(\mathcal{F}_h).
