Combining all the above, we have
\begin{align*}
\frac1{Z_t^B}\le\frac1{p_0(\mathcal{F}_h)}\exp\bigg(\mathbb{E}_{f\sim p_0^h}\bigg[\sum_{s=1}^{t-1}\big[-2\eta\epsilon_s(f(x_s, a_s)-f_*(x_s, a_s))+\eta h^2\big]+\lambda h\bigg]\bigg).
\end{align*}

We denote
\begin{align*}
w_s=2\eta\epsilon_s\{\widetilde f(x_s, a_s)-\mathbb{E}_{f\sim p_0^h}[f(x_s, a_s)]\}+(\gamma\lambda-\eta)\operatorname{LS}_s(\widetilde f)+\eta h^2,
\end{align*}
Then $w_s$ is $\mathcal{F}_s$-measurable. For $1\le k<t$, we have
\begin{align*}
\mathbb{E}\exp\bigg(\sum_{s=1}^{k}w_s\bigg)&=\mathbb{E}\bigg\{\exp\bigg(\sum_{s=1}^{k-1}w_s\bigg)\cdot\mathbb{E}[\exp(w_k)|\mathcal{F}_{k-1}]\bigg\},
\end{align*}
where
\begin{align*}
&\mathbb{E}[\exp(w_k)|\mathcal{F}_{k-1}]\\
&=\mathbb{E}\{\mathbb{E}[\exp(w_k)|\mathcal{G}_k]|\mathcal{F}_{k-1}\}\\
&\le\mathbb{E}\Big[\exp\Big(\frac{\eta^2}{2}\{\widetilde f(x_k, a_k)-\mathbb{E}_{f\sim p_0^h}[f(x_k, a_k)]\}^2+(\gamma\lambda-\eta)\operatorname{LS}_k(\widetilde f)+\eta h^2\Big)\Big|\mathcal{F}_{k-1}\Big]\\
