\begin{align*}
\mathbb{E}\exp\bigg(\sum_{s=1}^{t-1}w_s\bigg)\le\exp(0.75(t-1)h^2).
\end{align*}

\label{lemma:KL_reg}
Let $(\mathcal{X}, \mathcal{F}, P_0)$ be a probability space and $U(x)$ be a bounded measurable function. Then for any distribution $P$ on $(\mathcal{X}, \mathcal{F})$, we have
\begin{align*}
\mathbb{E}_{x\sim P}[U(x)]+\operatorname{KL}(P\|P_0)\ge-\log\mathbb{E}_{x\sim P_0}\exp(-U(x)),
\end{align*}
and equality holds for the distribution with density $\exp(-U)/\mathbb{E}_{P_0}\exp(-U)$ with respect to $P_0$.

\label{lemma:subgaussian}
Let $\{\mathcal{F}_t\}$ and $\{\mathcal{G}_t\}$ be filtrations such that $\mathcal{F}_{t-1}\subseteq\mathcal{G}_t\subseteq\mathcal{F}_t$. Let $\epsilon_t$ be $\mathcal{F}_t$-measurable and satisfy
\begin{align*}
\log\mathbb{E}[\exp(\lambda\epsilon_t)|\mathcal{G}_t]\le\lambda^2/8
\qquad\text{for every $\lambda\in\mathbb{R}$}.
\end{align*}
Let $\mu_t$ be $\mathcal{G}_t$-measurable with $|\mu_t|\le C$ almost surely, where $C>0$. For every $M\ge0$, we have
\begin{align*}
\mathbb{P}\bigg\{\sum_{t=1}^T\mu_t\epsilon_t\ge M\bigg\}\le\exp\Big(-\frac{2M^2}{C^2T}\Big).
\end{align*}
Therefore, for any $\delta\in(0,1)$, with probability at least $1-\delta$, we have
\begin{align*}
\sum_{t=1}^T\mu_t\epsilon_t\le C\sqrt{\frac T2\log(1/\delta)}.
\end{align*}
